"""Export "PDF combiné" de la veille : une synthèse mise en page (même
nomenclature Priorité 1/2 que le texte de la veille, voir main._format_draft)
suivie des PDF sources déposés, compilés à la suite et regroupés par thème
derrière une page de garde, dans l'ordre où ils apparaissent dans la
synthèse. Chaque titre de la synthèse est cliquable : vers la page source
correspondante si un PDF est embarqué plus loin dans le document, sinon vers
le lien de l'article pour une source ouverte (Tecsol, PV Magazine...).

Utilisé depuis la webapp sur les entrées de l'aperçu, éventuellement éditées
et filtrées (voir webapp.download_combined_pdf) — ne consomme/n'archive
rien, peut être régénéré autant de fois que voulu avant de cliquer "Valider".
Une entrée sans fichier associé et sans lien n'a simplement rien derrière
elle : elle apparaît dans la synthèse en texte simple, non cliquable.
"""
import base64
import html
import math
from datetime import date
from io import BytesIO
from pathlib import Path

from pypdf import PdfReader, PdfWriter
from pypdf.annotations import Link
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import cm
from reportlab.lib.utils import ImageReader
from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer

from main import _format_date_fr
from tracker_excel import extract_links

# Charte graphique bleu foncé / bleu clair du PDF (indépendante des couleurs
# vertes de l'interface web — voir webapp.py).
DARK_BLUE_HEX = "#0A1F44"
MID_BLUE_HEX = "#12406E"
ACCENT_BLUE_HEX = "#1C6FC9"
LIGHT_BLUE_HEX = "#D6E8F7"
DARK_BLUE = colors.HexColor(DARK_BLUE_HEX)
MID_BLUE = colors.HexColor(MID_BLUE_HEX)
ACCENT_BLUE = colors.HexColor(ACCENT_BLUE_HEX)
LIGHT_BLUE = colors.HexColor(LIGHT_BLUE_HEX)
MUTED_GREY = colors.HexColor("#8A97A8")
BODY_TEXT = colors.HexColor("#1E2733")

# Logo ENGIE officiel (assets/engie_logo.png, fond damier gris/blanc rendu
# transparent) encodé en base64 (voir README.md pour la procédure
# d'injection, même mécanisme que webapp._LOGO_B64). Si cette constante est
# vidée (fichier retiré/à remplacer), _draw_logo dessine alors un monogramme
# de repli dans les mêmes tons bleus — remplacé automatiquement dès que cette
# constante est renseignée, aucun autre changement de code nécessaire.
_ENGIE_LOGO_B64 = ""

BANNER_HEIGHT = 2.6 * cm


def _logo_image_reader() -> ImageReader | None:
    if not _ENGIE_LOGO_B64:
        return None
    return ImageReader(BytesIO(base64.b64decode(_ENGIE_LOGO_B64)))


_logo_aspect_cache: list[float] = []  # mémoïsation paresseuse (voir _logo_aspect_ratio)


def _logo_aspect_ratio() -> float:
    """Ratio largeur/hauteur du logo réel (le PNG ENGIE n'est pas
    carré, contrairement au monogramme de repli) — calculé une seule fois."""
    if not _logo_aspect_cache:
        logo = _logo_image_reader()
        iw, ih = logo.getSize() if logo is not None else (1, 1)
        _logo_aspect_cache.append(iw / ih)
    return _logo_aspect_cache[0]


def _draw_logo(c, x: float, y: float, height: float, center: bool = False) -> None:
    """Dessine le logo Engie sur la hauteur donnée, à sa largeur réelle
    (jamais déformé) : x est le bord gauche par défaut, ou le centre
    horizontal si center=True (pages de garde). Sans logo fourni
    (_ENGIE_LOGO_B64 vide), dessine un monogramme "E" de repli dans un badge
    carré de ce même côté `height`."""
    logo = _logo_image_reader()
    if logo is None:
        size = height
        left = x - size / 2 if center else x
        c.saveState()
        c.setFillColor(DARK_BLUE)
        c.roundRect(left, y, size, size, size * 0.18, fill=1, stroke=0)
        c.setFillColor(colors.white)
        c.setFont("Helvetica-Bold", size * 0.52)
        c.drawCentredString(left + size / 2, y + size * 0.30, "E")
        c.restoreState()
        return
    width = height * _logo_aspect_ratio()
    left = x - width / 2 if center else x
    c.drawImage(logo, left, y, width=width, height=height, mask="auto", preserveAspectRatio=True)


def _draw_credit_footer(c, center_x: float, y: float) -> None:
    """Mention de pied de page commune à toutes les pages du PDF combiné
    (synthèse + pages de garde des sources) : petit logo + "Réalisé avec
    StratIA — Service Marketing", centrée sur center_x."""
    text = "Réalisé avec StratIA — Service Marketing"
    logo_h = 0.32 * cm
    gap = 0.15 * cm
    logo_w = logo_h * _logo_aspect_ratio()
    c.setFont("Helvetica", 8)
    text_w = c.stringWidth(text, "Helvetica", 8)
    left = center_x - (logo_w + gap + text_w) / 2
    _draw_logo(c, left, y - logo_h * 0.15, logo_h)
    c.setFillColor(MUTED_GREY)
    c.drawString(left + logo_w + gap, y, text)


# Pictogrammes de thème pour les pages de garde (voir _draw_theme_icon) :
# dessinés en primitives reportlab (pas d'image externe) dans un repère local
# centré en (0, 0) et mis à l'échelle par `s` (taille cible en points) — le
# même style que le monogramme de repli du logo. Chaque fonction suppose que
# le canvas a déjà été translaté sur le centre de l'icône (voir
# _draw_theme_icon) et restaure elle-même son état.
def _icon_eolien(c, s):
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.05)
    c.setLineCap(1)
    hub_y = s * 0.06
    c.line(0, -s * 0.46, 0, hub_y)
    for angle in (90, 205, 335):
        a = math.radians(angle)
        c.line(0, hub_y, s * 0.38 * math.cos(a), hub_y + s * 0.38 * math.sin(a))
    c.setFillColor(colors.white)
    c.circle(0, hub_y, s * 0.05, fill=1, stroke=0)


def _icon_solaire(c, s):
    r = s * 0.2
    c.setFillColor(colors.white)
    c.circle(0, 0, r, fill=1, stroke=0)
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.045)
    c.setLineCap(1)
    for i in range(8):
        a = math.radians(i * 45)
        c.line((r + s * 0.06) * math.cos(a), (r + s * 0.06) * math.sin(a),
               (r + s * 0.19) * math.cos(a), (r + s * 0.19) * math.sin(a))


def _icon_agrivoltaisme(c, s):
    c.saveState()
    c.translate(0, s * 0.16)
    c.rotate(-12)
    w, h = s * 0.46, s * 0.24
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.035)
    c.rect(-w / 2, -h / 2, w, h, fill=0, stroke=1)
    c.line(-w / 6, -h / 2, -w / 6, h / 2)
    c.line(w / 6, -h / 2, w / 6, h / 2)
    c.line(-w / 2, 0, w / 2, 0)
    c.restoreState()
    c.saveState()
    c.translate(0, -s * 0.17)
    c.setFillColor(colors.white)
    r = s * 0.15
    p = c.beginPath()
    p.moveTo(0, -r)
    p.curveTo(r, -r * 0.25, r, r * 0.25, 0, r)
    p.curveTo(-r, r * 0.25, -r, -r * 0.25, 0, -r)
    p.close()
    c.drawPath(p, fill=1, stroke=0)
    c.restoreState()


def _icon_batteries(c, s):
    w, h = s * 0.46, s * 0.34
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.035)
    c.rect(-w / 2, -h / 2, w, h, fill=0, stroke=1)
    c.setFillColor(colors.white)
    c.rect(w / 2, -h * 0.14, w * 0.1, h * 0.28, fill=1, stroke=0)
    c.setFillColor(ACCENT_BLUE)
    bw, bh = s * 0.16, s * 0.3
    p = c.beginPath()
    p.moveTo(bw * 0.35, bh / 2)
    p.lineTo(-bw * 0.25, bh * 0.05)
    p.lineTo(bw * 0.05, bh * 0.05)
    p.lineTo(-bw * 0.35, -bh / 2)
    p.lineTo(bw * 0.25, -bh * 0.05)
    p.lineTo(-bw * 0.05, -bh * 0.05)
    p.close()
    c.drawPath(p, fill=1, stroke=0)


def _icon_hybride(c, s):
    r = s * 0.2
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.04)
    c.circle(-s * 0.11, 0, r, fill=0, stroke=1)
    c.circle(s * 0.11, 0, r, fill=0, stroke=1)


def _icon_hydroelectrique(c, s):
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.045)
    c.setLineCap(1)
    for row, dy in enumerate((-s * 0.02, s * 0.2)):
        offset = s * 0.11 if row else 0
        for i in range(-2, 2):
            cx = i * s * 0.22 + offset
            c.arc(cx - s * 0.11, dy - s * 0.06, cx + s * 0.11, dy + s * 0.06, 180, 180)


def _icon_partage(c, s):
    r = s * 0.26
    c.setFillColor(colors.white)
    c.wedge(-r, -r, r, r, 0, 110, fill=1, stroke=0)
    c.setFillColor(ACCENT_BLUE)
    c.wedge(-r, -r, r, r, 110, 130, fill=1, stroke=0)
    c.setFillColor(LIGHT_BLUE)
    c.wedge(-r, -r, r, r, 240, 120, fill=1, stroke=0)


def _icon_repowering(c, s):
    r = s * 0.24
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.065)
    c.setLineCap(1)
    start_deg, extent_deg = 35, 280
    c.arc(-r, -r, r, r, start_deg, extent_deg)
    end_a = math.radians(start_deg + extent_deg)
    tx, ty = r * math.cos(end_a), r * math.sin(end_a)
    tan_x, tan_y = -math.sin(end_a), math.cos(end_a)  # tangente (sens antihoraire)
    nx, ny = math.cos(end_a), math.sin(end_a)  # normale sortante
    head_len, head_w = s * 0.16, s * 0.09
    c.setFillColor(colors.white)
    p = c.beginPath()
    p.moveTo(tx + tan_x * head_len * 0.6, ty + tan_y * head_len * 0.6)
    p.lineTo(tx - tan_x * head_len * 0.4 + nx * head_w, ty - tan_y * head_len * 0.4 + ny * head_w)
    p.lineTo(tx - tan_x * head_len * 0.4 - nx * head_w, ty - tan_y * head_len * 0.4 - ny * head_w)
    p.close()
    c.drawPath(p, fill=1, stroke=0)


def _icon_concurrence(c, s):
    """Cible : simple et lisible en primitives (préféré à un trophée, dont
    les arcs de poignées ne rendaient pas correctement à cette échelle)."""
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.035)
    c.circle(0, 0, s * 0.26, fill=0, stroke=1)
    c.circle(0, 0, s * 0.16, fill=0, stroke=1)
    c.setFillColor(colors.white)
    c.circle(0, 0, s * 0.06, fill=1, stroke=0)


def _icon_building(c, s):
    w, h = s * 0.38, s * 0.5
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.035)
    c.rect(-w / 2, -h / 2, w, h, fill=0, stroke=1)
    c.setFillColor(colors.white)
    for row in range(3):
        for col in range(2):
            wx = -w / 2 + w * 0.18 + col * w * 0.44
            wy = -h / 2 + h * 0.14 + row * h * 0.27
            c.rect(wx, wy, w * 0.2, h * 0.14, fill=1, stroke=0)


def _icon_globe(c, s):
    r = s * 0.24
    c.setStrokeColor(colors.white)
    c.setLineWidth(s * 0.035)
    c.circle(0, 0, r, fill=0, stroke=1)
    c.ellipse(-r * 0.42, -r, r * 0.42, r, fill=0, stroke=1)
    c.line(-r, 0, r, 0)


_THEME_PICTO_B64 = {
    "EOLIEN": "",
    "SOLAIRE": "",
    "AGRIVOLTAÏSME": "",
    "BATTERIES / STOCKAGE": "",
    "HYDROELECTRIQUE": "",
}


_THEME_ICON_DRAWERS = {
    "EOLIEN": _icon_eolien,
    "SOLAIRE": _icon_solaire,
    "AGRIVOLTAÏSME": _icon_agrivoltaisme,
    "BATTERIES / STOCKAGE": _icon_batteries,
    "HYBRIDE": _icon_hybride,
    "HYDROELECTRIQUE": _icon_hydroelectrique,
    "PARTAGE DE LA VALEUR": _icon_partage,
    "REPOWERING": _icon_repowering,
    "CONCURRENCE": _icon_concurrence,
    "ENGIE R&B": _icon_building,
    "ENGIE": _icon_building,
    "ACTU GENERALE ENERGIE": _icon_globe,
}


_theme_picto_reader_cache: dict[str, ImageReader] = {}


def _theme_picto_reader(theme: str) -> ImageReader | None:
    """Image fournie pour ce thème (badge carré coloré avec pictogramme +
    libellé, voir _THEME_PICTO_B64) — amenée à être complétée/remplacée pour
    les autres thèmes, d'où le fallback sur un pictogramme dessiné
    (_THEME_ICON_DRAWERS) pour ceux qui n'en ont pas encore."""
    if theme not in _THEME_PICTO_B64:
        return None
    if theme not in _theme_picto_reader_cache:
        _theme_picto_reader_cache[theme] = ImageReader(BytesIO(base64.b64decode(_THEME_PICTO_B64[theme])))
    return _theme_picto_reader_cache[theme]


def _draw_theme_icon(c, theme: str, cx: float, cy: float, size: float) -> None:
    """Dessine le pictogramme du thème centré en (cx, cy), dans une boîte
    d'environ `size` de côté : l'image fournie si ce thème en a une
    (_THEME_PICTO_B64), sinon un pictogramme dessiné en primitives
    (_THEME_ICON_DRAWERS). Thème hors liste ou sans aucun des deux (ne
    devrait pas arriver, voir _valid_veille_theme) : rien plutôt qu'une
    erreur."""
    picto = _theme_picto_reader(theme)
    if picto is not None:
        c.drawImage(picto, cx - size / 2, cy - size / 2, width=size, height=size, mask="auto", preserveAspectRatio=True)
        return
    drawer = _THEME_ICON_DRAWERS.get(theme)
    if drawer is None:
        return
    c.saveState()
    c.translate(cx, cy)
    drawer(c, size)
    c.restoreState()


def _entry_pdf_files(e: dict) -> list[Path]:
    """PDF d'origine associés à cette entrée (peut en avoir plusieurs pour
    une note à pièces jointes multiples) — absent pour un article scrapé ou
    une note .txt/.md déposée à la main."""
    note = e.get("_note")
    if not note:
        return []
    return [f for f in note.get("_files", []) if isinstance(f, Path) and f.suffix.lower() == ".pdf" and f.exists()]


def _entry_url(e: dict) -> str | None:
    """URL externe d'une source ouverte (Tecsol, PV Magazine...), extraite de
    source_line — absente pour une note GreenUnivers (accès abonné/pdf)."""
    links = extract_links(e.get("source_line", ""))
    return links[0] if links else None


class _TrackedTitle(Paragraph):
    """Paragraphe de titre dont la position réelle sur la page est
    enregistrée à l'affichage (voir Canvas.absolutePosition) pour poser
    ensuite une annotation de lien cliquable vers la page du PDF source
    correspondant — la page cible n'est connue qu'une fois toutes les
    sections assemblées (voir build_combined_pdf), d'où cet enregistrement
    différé plutôt qu'un lien posé directement ici."""

    def __init__(self, text: str, style: ParagraphStyle, entry_index: int, registry: list[dict]):
        super().__init__(text, style)
        self._entry_index = entry_index
        self._registry = registry

    def draw(self):
        x0, y0 = self.canv.absolutePosition(0, 0)
        x1, y1 = self.canv.absolutePosition(self.width, self.height)
        self._registry.append({
            "entry_index": self._entry_index,
            "page": self.canv.getPageNumber() - 1,
            "rect": (min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)),
        })
        super().draw()


def _make_summary_page_decorator(run_date: date):
    """Bandeau d'en-tête (logo + titre + date, fond bleu foncé) et pied de
    page (numérotation) appliqués à chaque page de la synthèse."""
    def _decorate(c, doc):
        page_w, page_h = A4
        c.saveState()
        c.setFillColor(DARK_BLUE)
        c.rect(0, page_h - BANNER_HEIGHT, page_w, BANNER_HEIGHT, fill=1, stroke=0)
        logo_h = 1.15 * cm
        _draw_logo(c, 1.15 * cm, page_h - BANNER_HEIGHT + (BANNER_HEIGHT - logo_h) / 2, logo_h)
        text_x = 1.15 * cm + logo_h * _logo_aspect_ratio() + 0.5 * cm
        c.setFillColor(colors.white)
        c.setFont("Helvetica-Bold", 16)
        c.drawString(text_x, page_h - 1.35 * cm, "Veille hebdo ENGIE R&B")
        c.setFillColor(LIGHT_BLUE)
        c.setFont("Helvetica", 10.5)
        c.drawString(text_x, page_h - 1.95 * cm, _format_date_fr(run_date))
        _draw_credit_footer(c, page_w / 2, 1 * cm)
        c.setFillColor(MUTED_GREY)
        c.setFont("Helvetica", 7)
        c.drawRightString(page_w - 2 * cm, 1 * cm, f"page {doc.page}")
        c.restoreState()
    return _decorate


def _build_summary_pdf_bytes(entries: list[dict], run_date: date, link_registry: list[dict]) -> bytes:
    """Génère, en mémoire, les pages de synthèse : les actus groupées par
    priorité (même nomenclature que le texte final, voir main._format_draft),
    mises en page avec reportlab (s'enchaîne naturellement sur plusieurs
    pages si besoin). Les titres des entrées avec un PDF source embarqué sont
    suivis via _TrackedTitle (lien posé après coup, voir build_combined_pdf) ;
    ceux d'une source ouverte (URL) pointent directement vers cette URL."""
    buf = BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=A4,
        topMargin=BANNER_HEIGHT + 0.9 * cm, bottomMargin=1.6 * cm,
        leftMargin=2 * cm, rightMargin=2 * cm,
    )
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "EntryTitle", parent=styles["Normal"], fontName="Helvetica-Bold", fontSize=10.8,
        textColor=DARK_BLUE, spaceBefore=9, spaceAfter=2, leading=13.5,
    )
    link_title_style = ParagraphStyle("EntryTitleLink", parent=title_style, textColor=ACCENT_BLUE)
    body_style = ParagraphStyle(
        "EntryBody", parent=styles["Normal"], fontName="Helvetica", fontSize=9.6,
        leading=13, spaceAfter=1, textColor=BODY_TEXT,
    )
    source_style = ParagraphStyle(
        "EntrySource", parent=styles["Normal"], fontName="Helvetica-Oblique", fontSize=8,
        leading=10, spaceAfter=4, textColor=MUTED_GREY,
    )

    story = []
    for priority in ("P1", "P2"):
        indices = [i for i, e in enumerate(entries) if e["priority"] == priority]
        if not indices:
            continue
        for i in indices:
            e = entries[i]
            theme_tag = f'<font color="{ACCENT_BLUE_HEX}">[{html.escape(e["theme"])}]</font>'
            escaped_title = html.escape(e["title"])
            pdf_files = _entry_pdf_files(e)
            if pdf_files:
                story.append(_TrackedTitle(f"{theme_tag} {escaped_title}", title_style, i, link_registry))
            else:
                url = _entry_url(e)
                if url:
                    href = html.escape(url, quote=True)
                    story.append(Paragraph(f'{theme_tag} <link href="{href}"><u>{escaped_title}</u></link>', link_title_style))
                else:
                    story.append(Paragraph(f"{theme_tag} {escaped_title}", title_style))
            story.append(Paragraph(html.escape(e["summary"]), body_style))
            story.append(Paragraph(html.escape(e["source_line"]), source_style))
        story.append(Spacer(1, 4))

    if not entries:
        story.append(Paragraph("Aucune actualité à exporter.", body_style))

    decorate = _make_summary_page_decorator(run_date)
    doc.build(story, onFirstPage=decorate, onLaterPages=decorate)
    return buf.getvalue()


def _build_theme_cover_bytes(theme: str, run_date: date) -> bytes:
    """Page de garde pleine page (fond bleu foncé, thème en grand) insérée
    avant le groupe de PDF sources de ce thème."""
    from reportlab.pdfgen.canvas import Canvas

    buf = BytesIO()
    page_w, page_h = A4
    c = Canvas(buf, pagesize=A4)
    c.setFillColor(DARK_BLUE)
    c.rect(0, 0, page_w, page_h, fill=1, stroke=0)

    # Cercle décoratif en fond, légèrement plus clair, pour éviter un aplat
    # trop nu — centré sur le bloc icône+titre plutôt qu'au milieu strict de
    # la page (le pied de page laisse un peu de respiration en bas).
    center_y = page_h * 0.56
    c.saveState()
    c.setFillColor(MID_BLUE)
    c.setFillAlpha(0.55)
    c.circle(page_w / 2, center_y, page_w * 0.42, fill=1, stroke=0)
    c.restoreState()

    # Logo en petit, coin haut-gauche (comme un en-tête de courrier) : le
    # pictogramme du thème ci-dessous devient l'élément visuel principal.
    _draw_logo(c, 1.3 * cm, page_h - 2.1 * cm, 0.9 * cm)

    icon_size = 2.0 * cm
    _draw_theme_icon(c, theme, page_w / 2, center_y + 1.85 * cm, icon_size)

    max_width = page_w - 4 * cm
    font_size = 34
    while c.stringWidth(theme, "Helvetica-Bold", font_size) > max_width and font_size > 14:
        font_size -= 2
    c.setFillColor(colors.white)
    c.setFont("Helvetica-Bold", font_size)
    c.drawCentredString(page_w / 2, center_y - 0.35 * cm, theme)

    c.setStrokeColor(ACCENT_BLUE)
    c.setLineWidth(2)
    rule_y = center_y - 1.25 * cm
    c.line(page_w / 2 - 2.5 * cm, rule_y, page_w / 2 + 2.5 * cm, rule_y)

    c.setFillColor(LIGHT_BLUE)
    c.setFont("Helvetica", 11)
    c.drawCentredString(page_w / 2, rule_y - 0.9 * cm, "Sources")

    _draw_credit_footer(c, page_w / 2, 1 * cm)
    c.showPage()
    c.save()
    return buf.getvalue()


def build_combined_pdf(entries: list[dict], run_date: date | None = None) -> bytes:
    """PDF unique : la synthèse (voir _build_summary_pdf_bytes) suivie des
    PDF sources, regroupés par thème (page de garde + PDF du groupe) dans
    l'ordre de première apparition du thème parmi les entrées — c'est-à-dire
    le même ordre que dans la synthèse elle-même. Un thème sans aucun PDF
    source (que des articles scrapés/notes texte) n'a pas de page de garde."""
    run_date = run_date or date.today()
    link_registry: list[dict] = []
    summary_bytes = _build_summary_pdf_bytes(entries, run_date, link_registry)
    summary_reader = PdfReader(BytesIO(summary_bytes))
    n_summary_pages = len(summary_reader.pages)

    writer = PdfWriter()
    for page in summary_reader.pages:
        writer.add_page(page)

    theme_order: list[str] = []
    theme_to_indices: dict[str, list[int]] = {}
    entry_files: dict[int, list[Path]] = {}
    for i, e in enumerate(entries):
        files = _entry_pdf_files(e)
        if not files:
            continue
        entry_files[i] = files
        theme = e["theme"]
        if theme not in theme_to_indices:
            theme_to_indices[theme] = []
            theme_order.append(theme)
        theme_to_indices[theme].append(i)

    entry_target_page: dict[int, int] = {}
    current_page = n_summary_pages
    for theme in theme_order:
        cover_reader = PdfReader(BytesIO(_build_theme_cover_bytes(theme, run_date)))
        for page in cover_reader.pages:
            writer.add_page(page)
        current_page += len(cover_reader.pages)
        for i in theme_to_indices[theme]:
            entry_target_page[i] = current_page
            for pdf_path in entry_files[i]:
                reader = PdfReader(str(pdf_path))
                for page in reader.pages:
                    writer.add_page(page)
                current_page += len(reader.pages)

    for item in link_registry:
        target = entry_target_page.get(item["entry_index"])
        if target is None:  # entrée décochée entre-temps ou sans PDF : pas de cible, pas de lien
            continue
        writer.add_annotation(
            page_number=item["page"],
            annotation=Link(rect=item["rect"], target_page_index=target),
        )

    out = BytesIO()
    writer.write(out)
    return out.getvalue()
